import{c as o,Q as t,j as d,m as s}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Fusion 架構 Phase 1 落地驗證（GLM-5.2 協作）","description":"","frontmatter":{"title":"Fusion 架構 Phase 1 落地驗證（GLM-5.2 協作）","date":"2026-07-09T00:00:00.000Z","status":"done","method":"逐項驗證 4 個優化項是否在 Claude Code 現有功能下可落地；每項附檔案:行號佐證","parent-report":"research/reports/2026-07-09-fusion-architecture-design-plan.md","scope":"§2.3 Claude Code Phase 1 — Sidekick via Sub-agent（現有能力,零修改）","type":"architecture-validation","validator":"GLM-5.2"},"headers":[],"relativePath":"research/reports/2026-07-09-fusion-glm-architecture-validation.md","filePath":"research/reports/2026-07-09-fusion-glm-architecture-validation.md","lastUpdated":1785909234000}'),i={name:"research/reports/2026-07-09-fusion-glm-architecture-validation.md"};function c(a,e,l,r,n,m){return t(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="fusion-架構-phase-1-落地驗證" tabindex="-1">Fusion 架構 Phase 1 落地驗證 <a class="header-anchor" href="#fusion-架構-phase-1-落地驗證" aria-label="Permalink to &quot;Fusion 架構 Phase 1 落地驗證&quot;">​</a></h1><blockquote><p>本報告驗證 <code>2026-07-09-fusion-architecture-design-plan.md</code> §2.3 Phase 1（「現有能力,零修改」）的四個優化項是否在 Claude Code 現有功能下可落地。 驗證者: GLM-5.2（ceiling 檔,開源）。今天: 2026-07-09。</p></blockquote><h2 id="驗證對象-報告-§2-3-原文" tabindex="-1">驗證對象（報告 §2.3 原文） <a class="header-anchor" href="#驗證對象-報告-§2-3-原文" aria-label="Permalink to &quot;驗證對象（報告 §2.3 原文）&quot;">​</a></h2><p>Phase 1 主張: workspace 現有 <code>multi-mode-skill</code> + <code>multi-mode-agent</code> 已近似 Sidekick 模式,只需「改使用模式」不改架構。四個優化項:</p><ol><li>主對話預設委派機械任務給 cost 檔 sidekick,只在「規劃/歧義/審查」時親做</li><li>sidekick 回報只含結論 + 檔案:行號（delegation-protocol.md §4 既有規則）</li><li>主對話的 cache 前綴保持穩定（context-management.md Static First 既有規則）</li><li>用 <code>claude-progress.json</code> checkpoint 模擬 sidekick 持久性</li></ol><h2 id="驗證方法-5-項查證" tabindex="-1">驗證方法（5 項查證） <a class="header-anchor" href="#驗證方法-5-項查證" aria-label="Permalink to &quot;驗證方法（5 項查證）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>查證項</th><th>檔案</th><th>結論</th></tr></thead><tbody><tr><td>1</td><td>agent 是否支援 model override + mode 注入</td><td><code>.claude/agents/multi-mode-agent.md</code></td><td>✅ 支援</td></tr><tr><td>2</td><td>router 是否支援「預設委派」邏輯</td><td><code>.claude/skills/multi-mode-skill/SKILL.md</code></td><td>✅ 支援</td></tr><tr><td>3</td><td>§4 回報合約是否已落地</td><td><code>.claude/refs/delegation-protocol.md</code></td><td>✅ 已落地</td></tr><tr><td>4</td><td>Static First 規則是否存在</td><td><code>.claude/rules/context-management.md</code></td><td>✅ 存在</td></tr><tr><td>5</td><td>checkpoint 機制是否已有實作</td><td><code>schemas/progress.schema.json</code> + <code>.claude/hooks/session-init.sh</code> + <code>.claude/skills/multi-mode-skill/SKILL.md</code> §4</td><td>✅ 已實作</td></tr></tbody></table><hr><h2 id="逐項驗證" tabindex="-1">逐項驗證 <a class="header-anchor" href="#逐項驗證" aria-label="Permalink to &quot;逐項驗證&quot;">​</a></h2><h3 id="優化項-1-主對話預設委派機械任務給-cost-檔-sidekick-只在「規劃-歧義-審查」時親做" tabindex="-1">優化項 1: 主對話預設委派機械任務給 cost 檔 sidekick,只在「規劃/歧義/審查」時親做 <a class="header-anchor" href="#優化項-1-主對話預設委派機械任務給-cost-檔-sidekick-只在「規劃-歧義-審查」時親做" aria-label="Permalink to &quot;優化項 1: 主對話預設委派機械任務給 cost 檔 sidekick,只在「規劃/歧義/審查」時親做&quot;">​</a></h3><p><strong>判定: ✅ 可落地</strong> — 既有功能/規則已支撐,無需修改。</p><p><strong>佐證（檔案:行號）</strong>:</p><ul><li><code>.claude/agents/multi-mode-agent.md:8</code>（frontmatter）: <code>model: sonnet</code> 為預設,但 <strong>parent 於 spawn 時依任務分類綁定 model + 注入 tier 指令</strong> — 明確支援 model override。</li><li><code>.claude/agents/multi-mode-agent.md:13-15</code>（不變式）: 「你的 model 由 parent 在 spawn 時綁定,不可自切」「parent 會在 task description 注入 <code>[mode: cost|quality|ceiling|frontier]</code>」— mode 注入機制落地。</li><li><code>.claude/skills/multi-mode-skill/SKILL.md:§1</code>（router 核心表）: 「0–1 位置數 → tier cost → model haiku → inline/spawn 1 worker」— 機械任務自動路由到 cost 檔,正是 sidekick 的角色定位。</li><li><code>.claude/skills/multi-mode-skill/SKILL.md:§2</code>（委派門檻）: 「任一成立 → spawn multi-mode-agent（注入 <code>[mode: ...]</code> + 對應 <code>model</code> override）」+ spawn 範例 <code>Agent(subagent_type=&quot;multi-mode-agent&quot;, model=&quot;opus&quot;, prompt=&quot;[mode: ceiling] ...&quot;)</code> — spawn 時綁定 cost 檔 model（haiku）即可作 sidekick。</li><li><code>.claude/refs/delegation-protocol.md:§1</code>（指揮官不下場）: 「預設委派、例外親做」+ 「T0 親做例外: 0–1 檔且 ≤3 次工具呼叫;對話/裁決/確認 gate」— 「只在規劃/歧義/審查時親做」已有量化門檻。</li><li><code>.claude/refs/delegation-protocol.md:§1 T1 一律委派</code>: 「讀取 &gt;3 檔或預期輸出 &gt;100 行、掃 repo、批次改檔、跑驗證迭代——主對話只進結論」— 機械任務委派規則已落地。</li></ul><p><strong>落地姿勢</strong>: 主對話遇到機械任務 → spawn <code>multi-mode-agent</code> with <code>model=&quot;haiku&quot;</code>, <code>prompt=&quot;[mode: cost] &lt;task&gt;&quot;</code>。這是 §1 表的 cost 行 + §2 spawn 範例的直接組合,零修改。</p><hr><h3 id="優化項-2-sidekick-回報只含結論-檔案-行號-delegation-protocol-md-§4-既有規則" tabindex="-1">優化項 2: sidekick 回報只含結論 + 檔案:行號（delegation-protocol.md §4 既有規則） <a class="header-anchor" href="#優化項-2-sidekick-回報只含結論-檔案-行號-delegation-protocol-md-§4-既有規則" aria-label="Permalink to &quot;優化項 2: sidekick 回報只含結論 + 檔案:行號（delegation-protocol.md §4 既有規則）&quot;">​</a></h3><p><strong>判定: ✅ 可落地</strong> — 既有功能/規則已支撐,無需修改。</p><p><strong>佐證（檔案:行號）</strong>:</p><ul><li><code>.claude/refs/delegation-protocol.md:§4 回報合約</code>: <ul><li>「只回<strong>結論 + 檔案:行號</strong>;禁貼大段原文進 parent context」</li><li>「長產物（&gt;30 行）→ 存檔（scratchpad 或指定路徑）,回傳路徑 + ≤10 行摘要」</li><li>「輸出只含結果:不加確認句、不加開場白;要求 JSON 就回純 JSON」</li></ul></li><li><code>.claude/agents/multi-mode-agent.md:輸出契約</code>（檔尾）: 「回報 parent 用結構化摘要（非原始 dump）: <code>{mode, model, 達標?, 驗證前5/後5行, open_questions, 升級建議}</code>」— sidekick（multi-mode-agent）的回報 schema 已對齊 §4 合約,且明文「不加確認句」「不 self-retry」。</li><li><code>.claude/skills/multi-mode-skill/SKILL.md:§4</code>（Context 不爆）: 「主對話只收<strong>摘要</strong>」— 與 §4 合約同向,router 端也要求摘要回報。</li></ul><p><strong>落地姿勢</strong>: sidekick（multi-mode-agent）的輸出契約已內建結論 + 檔案:行號 + 摘要格式,parent 不需額外指示。零修改。</p><hr><h3 id="優化項-3-主對話的-cache-前綴保持穩定-context-management-md-static-first-既有規則" tabindex="-1">優化項 3: 主對話的 cache 前綴保持穩定（context-management.md Static First 既有規則） <a class="header-anchor" href="#優化項-3-主對話的-cache-前綴保持穩定-context-management-md-static-first-既有規則" aria-label="Permalink to &quot;優化項 3: 主對話的 cache 前綴保持穩定（context-management.md Static First 既有規則）&quot;">​</a></h3><p><strong>判定: ✅ 可落地</strong> — 既有功能/規則已支撐,無需修改。</p><p><strong>佐證（檔案:行號）</strong>:</p><ul><li><code>.claude/rules/context-management.md:Prompt Caching（Static First）</code>: <ul><li>「CLAUDE.md = 最穩定快取前綴,永遠放最前、session 內不動」</li><li>「<strong>Mid-session 禁止</strong>切換模型/增刪 tool/改 CLAUDE.md（破快取）;能力升級需求 → sub-agent 檔位 override（載體 <code>multi-mode-agent</code>）或新 session,不切主對話模型」</li></ul></li><li><code>.claude/skills/multi-mode-skill/SKILL.md:§0 不變式</code>: 「model 在 spawn 時綁定,主對話 mid-session 不切 model（破 prompt cache,見 context-management.md）。要換檔位 → 用 sub-agent <code>model</code> override 或新 session」— router 明文遵守 Static First。</li><li><code>.claude/skills/multi-mode-skill/SKILL.md:§4</code>（NLAH）: 「原始目標放 HEAD,最新工具輸出放 TAIL,動態狀態放中間」— cache 前綴穩定性 + 動態內容放置規則並存。</li><li><code>.claude/agents/multi-mode-agent.md:isolation: worktree</code>（frontmatter）: sidekick 在獨立 worktree 執行,context 與主對話隔離 → sidekick 的 context 變動不污染主對話 cache 前綴。</li></ul><p><strong>落地姿勢</strong>: Phase 1 的 sidekick 是 sub-agent spawn（新 context）,主對話模型/工具/CLAUDE.md 全程不動 → cache 前綴天然穩定。這正是 context-management.md「能力升級 → sub-agent 檔位 override」的設計意圖。零修改。</p><hr><h3 id="優化項-4-用-claude-progress-json-checkpoint-模擬-sidekick-持久性" tabindex="-1">優化項 4: 用 <code>claude-progress.json</code> checkpoint 模擬 sidekick 持久性 <a class="header-anchor" href="#優化項-4-用-claude-progress-json-checkpoint-模擬-sidekick-持久性" aria-label="Permalink to &quot;優化項 4: 用 `claude-progress.json` checkpoint 模擬 sidekick 持久性&quot;">​</a></h3><p><strong>判定: ⚠️ 需修改</strong> — checkpoint 機制本身已實作且可用,但<strong>現有實作是為「跨 session 長任務 resume」設計,並非為「sidekick 跨 spawn 狀態恢復」設計</strong>;要模擬 sidekick 持久性需小幅調整使用模式（非架構修改）。</p><p><strong>佐證（檔案:行號）</strong>:</p><p><strong>已落地部分（checkpoint 基礎設施完備）</strong>:</p><ul><li><code>schemas/progress.schema.json</code>: 完整 schema 已定義 — <code>task_id</code> / <code>title</code> / <code>status</code> / <code>steps[]</code>（含 id/title/status/notes）/ <code>current_step</code> / <code>next_action</code> / <code>sessions[]</code> / <code>reminders[]</code>。可承載 sidekick 的 goal + 已完成 + 下一步。</li><li><code>.claude/hooks/session-init.sh</code>: 多處 <code>PROGRESS_JSON=&quot;$WORKSPACE_DIR/claude-progress.json&quot;</code> + <code>if [ -f &quot;$PROGRESS_JSON&quot; ]; then python3 ...</code> — session 啟動時自動讀取 checkpoint。</li><li><code>.claude/skills/multi-mode-skill/SKILL.md:§4 防衰退</code>: 「每輪寫 <code>claude-progress.json</code>（goal + 成功條件 + 已完成 + 下一步）;不依賴 compact 後記憶」— router 已內建 checkpoint 寫入。</li><li><code>.claude/skills/multi-mode-skill/SKILL.md:§5 /loop</code>: 「OBSERVE 讀 <code>claude-progress.json</code>（無 → 視為首輪,建立 goal + 成功條件）」— 跨 fire 狀態恢復已實作。</li><li><code>.claude/skills/handoff/SKILL.md</code>: 整個 skill 處理 <code>claude-progress.json</code> 建立/更新,交接流程完備。</li></ul><p><strong>需修改部分（用於 sidekick 持久性,非現有用途）</strong>:</p><ol><li><p><strong>語義不對齊</strong>: 現有 schema 的 <code>steps[]</code> / <code>current_step</code> / <code>next_action</code> 是為「主對話跨 session 長任務」設計的單一任務狀態。Fusion 報告 §2.3 的 sidekick 持久性需求是「sidekick 每次 spawn 時讀取 checkpoint 恢復狀態」,即 <strong>sidekick 自身的執行狀態跨多次 spawn 保持</strong>。兩者粒度不同:</p><ul><li>現有: 一個主任務的進度（主對話視角）</li><li>Fusion 需求: 一個 sidekick agent 的累積 context（sidekick 視角,可能服務多個主任務）</li></ul></li><li><p><strong>gitignored + ephemeral 限制（重要 caveat）</strong>:</p><ul><li><code>.gitignore:claude-progress.json</code> — 檔案不進 git。</li><li><code>.claude/skills/handoff/SKILL.md</code> 鐵律: 「<code>claude-progress.json</code> 是 <strong>gitignored + 遠端容器 ephemeral 會消失</strong> → 交接內容必須在 <code>memory/MEMORY.md</code>（Git 追蹤）<strong>自足</strong>」</li><li><code>.claude/skills/handoff/GOTCHAS.md</code> G4: 「下一 session（雲端 fresh clone）依 MEMORY『見 claude-progress.json round2』找佇列 → 檔案不存在（gitignored + ephemeral 容器）」— 已有實證失敗案例。</li><li>含義: 在雲端 / fresh clone 環境,checkpoint 會消失 → sidekick 持久性模擬在這些環境<strong>失效</strong>。本機 CLI 環境則可用。</li></ul></li><li><p><strong>sidekick 讀取入口缺失</strong>: 現有 <code>session-init.sh</code> 是 session 啟動時讀,但 sidekick 是 sub-agent spawn（非 session 啟動）。<code>multi-mode-agent.md</code> 的「The Loop 六階段」OBSERVE 步驟是「改動前讀目標 exports + 直接 caller + 共用 utility」,<strong>未明文讀 <code>claude-progress.json</code></strong>。sidekick 要用 checkpoint 恢復狀態,需在 spawn prompt 中顯式指示「先讀 <code>claude-progress.json</code> 的 <code>&lt;sidekick-task-id&gt;</code> 段」,或在 multi-mode-agent.md OBSERVE 加一行。</p></li></ol><p><strong>具體修改建議（小幅,不改架構）</strong>:</p><ul><li><strong>選項 A（最小改動,推薦）</strong>: 在主對話 spawn sidekick 的 prompt 中加一句:「先 Read <code>claude-progress.json</code> 的 <code>steps[].notes</code> 中 <code>&lt;本 sidekick 的 task_id&gt;</code> 相關段落恢復狀態,完成後 Write 更新該段」。這是 prompt 層調整,不改任何檔案。</li><li><strong>選項 B（agent 層內化）</strong>: 在 <code>.claude/agents/multi-mode-agent.md</code> 的 OBSERVE 步驟加一行:「若 parent prompt 標記 <code>[resume: &lt;task_id&gt;]</code> → 先 Read <code>claude-progress.json</code> 找對應 step 恢復狀態」。改 1 行,讓 sidekick 具備 checkpoint resume 能力。</li><li><strong>選項 C（schema 層）</strong>: 在 <code>schemas/progress.schema.json</code> 加一個 <code>sidekick_state</code> 可選欄位,專門存 sidekick 的累積 context。改 schema,但向後相容（optional）。</li></ul><p><strong>為何不是 ❌</strong>: checkpoint 基礎設施（schema + hooks + skill）已完備,語義不對齊是使用模式問題,可透過 prompt 指示或 1 行 agent 規則調整解決,非依賴未確認的 Claude Code 功能。報告 §2.3 自己也標明這是「現狀替代方案」「不是真正的 cache 持久化,但可減少重複 context 建構的 token 開銷」— 定位為模擬,非真正持久化,與本判定的 ⚠️ 一致。</p><hr><h2 id="統計" tabindex="-1">統計 <a class="header-anchor" href="#統計" aria-label="Permalink to &quot;統計&quot;">​</a></h2><table tabindex="0"><thead><tr><th>優化項</th><th>判定</th><th>依賴</th><th>是否需修改</th></tr></thead><tbody><tr><td>1. 預設委派 cost 檔 sidekick</td><td>✅ 可落地</td><td>multi-mode-agent model override + mode 注入; router §1 表; delegation-protocol §1</td><td>否</td></tr><tr><td>2. sidekick 回報結論 + 檔案:行號</td><td>✅ 可落地</td><td>delegation-protocol §4; multi-mode-agent 輸出契約</td><td>否</td></tr><tr><td>3. 主對話 cache 前綴穩定</td><td>✅ 可落地</td><td>context-management.md Static First; router §0 不變式; agent worktree isolation</td><td>否</td></tr><tr><td>4. claude-progress.json 模擬持久性</td><td>⚠️ 需修改</td><td>checkpoint 基礎設施已完備,但語義/入口/ephemeral 限制需小調整</td><td>是（prompt 層或 1 行 agent 規則）</td></tr></tbody></table><p><strong>合計: ✅×3 · ⚠️×1 · ❌×0</strong></p><h2 id="阻擋性問題" tabindex="-1">阻擋性問題 <a class="header-anchor" href="#阻擋性問題" aria-label="Permalink to &quot;阻擋性問題&quot;">​</a></h2><p><strong>無阻擋性問題</strong>。Phase 1 的 4 個優化項均可在 Claude Code 現有功能下落地:</p><ul><li>3 項零修改直接可用（既有規則/功能完全覆蓋）</li><li>1 項（checkpoint 持久性）需小幅使用模式調整,但基礎設施已完備,不依賴任何未確認的 Claude Code 功能</li></ul><p><strong>非阻擋性 caveat（需後續注意）</strong>:</p><ol><li><strong>ephemeral 環境失效</strong>: 優化項 4 的 checkpoint 模擬在雲端 / fresh clone 環境會因 <code>claude-progress.json</code> gitignored 而失效（已有 handoff GOTCHAS G4 實證）。本機 CLI 環境可用。若 Fusion 架構要在雲端穩定運行,sidekick 狀態需改存 git-tracked 路徑（如 <code>memory/MEMORY.md</code> 或獨立的 git-tracked sidekick state 檔）。</li><li><strong>Phase 2 才是真阻塞</strong>: 報告 §2.3 Phase 2（persistent sidekick with cached context）需 Claude Code 新功能,目前只能用 checkpoint 模擬。這是報告自己已標明的限制,非 Phase 1 問題。</li><li><strong>「預設委派」是行為紀律非強制 gate</strong>: 優化項 1 的「預設委派」依賴主對話遵守 delegation-protocol §1,目前是 auto-load 規則 + SKILL 路由建議,<strong>無 PreToolUse 硬 gate 強制</strong>。若要確保主對話不「偷做」機械任務,需評估是否加 hook（但這超出 Phase 1「零修改」範圍,屬 Phase 2+ 議題）。</li></ol><h2 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to &quot;結論&quot;">​</a></h2><p>報告 §2.3 Phase 1「現有能力,零修改」的定位<strong>基本準確</strong>: 3/4 優化項確實零修改可用,1/4 需小幅使用模式調整（非架構修改）。Phase 1 可作為 Fusion 架構的渐进落地起點,無阻塞。報告對 Phase 2 限制的預告（persistent sidekick 需新功能）也與本驗證一致 — checkpoint 模擬是合理的過渡方案,但不是長期答案。</p>',48)])])}const p=o(i,[["render",c]]);export{g as __pageData,p as default};
